import{_ as a,c as r,o as e,ag as t}from"./chunks/framework.ymCRTBvy.js";const y=JSON.parse('{"title":"1.3_删除Storyboard文件及相关引用","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/mvvm/1.3_删除Storyboard文件及相关引用.md","filePath":"uikit/mvvm/1.3_删除Storyboard文件及相关引用.md"}'),i={name:"uikit/mvvm/1.3_删除Storyboard文件及相关引用.md"};function d(l,o,n,c,s,p){return e(),r("div",null,o[0]||(o[0]=[t('<h1 id="_1-3-删除storyboard文件及相关引用" tabindex="-1">1.3_删除Storyboard文件及相关引用 <a class="header-anchor" href="#_1-3-删除storyboard文件及相关引用" aria-label="Permalink to &quot;1.3_删除Storyboard文件及相关引用&quot;">​</a></h1><h2 id="移除项目中的storyboard文件" tabindex="-1">移除项目中的Storyboard文件 <a class="header-anchor" href="#移除项目中的storyboard文件" aria-label="Permalink to &quot;移除项目中的Storyboard文件&quot;">​</a></h2><p>在iOS 18纯代码项目中，移除Storyboard文件是至关重要的一步。这能让你完全掌控UI布局，避免不必要的复杂性。许多开发者发现，纯代码方式提供了更高的灵活性和更精细的控制。大约70%的专业iOS开发者更倾向于使用纯代码进行UI开发，尤其是在大型项目中。</p><h2 id="删除main-storyboard文件" tabindex="-1">删除Main.storyboard文件 <a class="header-anchor" href="#删除main-storyboard文件" aria-label="Permalink to &quot;删除Main.storyboard文件&quot;">​</a></h2><p>首先，你需要从项目中物理删除<code>Main.storyboard</code>文件。这个文件通常位于你的项目导航器中，与<code>AppDelegate.swift</code>和<code>SceneDelegate.swift</code>在同一层级。</p><ol><li>在Xcode的项目导航器中，找到并选中<code>Main.storyboard</code>文件。</li><li>右键点击该文件，选择“Delete”（删除）。</li><li>在弹出的对话框中，选择“Move to Trash”（移到废纸篓）。🗑️ 这样做可以确保文件从你的硬盘中彻底移除，而不是仅仅从项目中移除引用。</li></ol><h2 id="清理项目设置中的storyboard引用" tabindex="-1">清理项目设置中的Storyboard引用 <a class="header-anchor" href="#清理项目设置中的storyboard引用" aria-label="Permalink to &quot;清理项目设置中的Storyboard引用&quot;">​</a></h2><p>仅仅删除文件是不够的，你还需要告诉Xcode你的项目不再使用Storyboard。这涉及到修改项目的配置设置。</p><ul><li><p><strong>目标设置</strong>：</p><ol><li>在Xcode的项目导航器中，点击你的项目名称（通常是顶部的蓝色图标）。</li><li>在主编辑区域中，选择“TARGETS”（目标）下的你的应用目标。</li><li>点击“General”（通用）选项卡。</li><li>向下滚动到“Deployment Info”（部署信息）部分。</li><li>你会看到一个名为“Main Interface”（主界面）的下拉菜单或文本框。这里通常会显示“Main”。你需要清空这个字段。</li></ol><p>清空这个字段后，Xcode就不会再尝试加载一个不存在的Storyboard文件了。这是一个关键步骤，确保你的应用能够顺利启动。</p></li></ul><h2 id="移除info-plist中的storyboard键" tabindex="-1">移除Info.plist中的Storyboard键 <a class="header-anchor" href="#移除info-plist中的storyboard键" aria-label="Permalink to &quot;移除Info.plist中的Storyboard键&quot;">​</a></h2><p><code>Info.plist</code>文件是iOS应用的重要配置文件，它包含了应用启动时所需的各种元数据。Storyboard的引用也可能存在于此。</p><ol><li><p>在项目导航器中，找到并打开<code>Info.plist</code>文件。</p></li><li><p>寻找名为<code>Application Scene Manifest</code>的键。展开它。</p></li><li><p>在<code>Scene Configuration</code>下，找到<code>Application Session Role</code>。</p></li><li><p>展开<code>Item 0 (Default Configuration)</code>。</p></li><li><p>你会看到一个名为<code>Storyboard Name</code>的键，其值为<code>Main</code>。</p></li><li><p>选中这个<code>Storyboard Name</code>键，然后点击底部的减号（-）按钮将其删除。</p><p>删除这个键是确保系统不再尝试加载Storyboard的最后一步。完成这些步骤后，你的项目就完全摆脱了Storyboard的束缚，为纯代码UI开发做好了准备！🎉</p></li></ol><h2 id="验证storyboard引用是否完全移除" tabindex="-1">验证Storyboard引用是否完全移除 <a class="header-anchor" href="#验证storyboard引用是否完全移除" aria-label="Permalink to &quot;验证Storyboard引用是否完全移除&quot;">​</a></h2><p>为了确保所有Storyboard引用都已成功移除，你可以进行一次快速验证。</p><ul><li><p><strong>构建并运行项目</strong>：</p><ol><li>按下<code>Cmd + B</code>构建你的项目。</li><li>按下<code>Cmd + R</code>运行你的项目。</li></ol><p>如果项目成功构建并运行，并且没有出现任何关于找不到Storyboard的错误，那么恭喜你！你已经成功地将Storyboard从你的项目中移除了。现在，你可以完全专注于使用纯代码构建你的用户界面了。这为你打开了无限的可能性，让你能够更灵活、更高效地开发iOS应用。🚀</p></li></ul>',15)]))}const _=a(i,[["render",d]]);export{y as __pageData,_ as default};
